{
  "schemaVersion": "0.2",
  "slug": "icon",
  "name": "Icon",
  "status": "experimental",
  "purpose": "Decorative or semantic glyph with explicit RTL behavior.",
  "scenarios": [
    "Show a directional glyph that flips in RTL",
    "Preserve a symmetric icon across reading directions",
    "Provide a locale-aware icon that the consumer localizes"
  ],
  "props": {
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible name for the icon."
    },
    "mode": {
      "type": "enum",
      "required": false,
      "description": "RTL behavior for the icon.",
      "values": [
        "mirror",
        "preserve",
        "localized"
      ],
      "default": "preserve"
    },
    "children": {
      "type": "node",
      "required": false,
      "description": "Optional SVG or glyph content; a default arrow is used when omitted."
    }
  },
  "variants": [
    {
      "name": "mode",
      "values": [
        "mirror",
        "preserve",
        "localized"
      ],
      "default": "preserve",
      "description": "Controls whether the icon is mirrored, preserved, or localized for RTL."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Icon is rendered with its declared mode."
    }
  ],
  "composition": {
    "allowedParents": [
      "button",
      "alert",
      "app-shell",
      "page"
    ],
    "allowedChildren": [
      "svg"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not hide the accessible name when the icon conveys meaning.",
    "Do not mirror symmetric icons; use mode=preserve."
  ],
  "a11y": {
    "role": "img",
    "keyboard": [],
    "focus": "Icon is not focusable; it is decorative or labelled by a parent.",
    "labeling": "A visible or aria-label accessible name is required when the icon conveys meaning.",
    "wcag": [
      "1.1.1"
    ]
  },
  "responsive": {
    "strategy": "Scales with the font size of its parent. No breakpoint-specific behavior.",
    "breakpoints": {
      "compact": "Inherits font size.",
      "medium": "Inherits font size.",
      "large": "Inherits font size."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. mode=mirror applies a scaleX transform; mode=preserve keeps the glyph; mode=localized defers to the consumer glyph.",
    "mirroredValues": [
      "mirror"
    ]
  },
  "dataAi": {
    "role": "icon",
    "states": [
      "mirror",
      "preserve",
      "localized"
    ],
    "intents": [
      "signal-meaning"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export interface IconProps {
  /** Accessible name for the icon. */
  label: string
  /** RTL behavior for the icon. */
  mode?: 'mirror' | 'preserve' | 'localized'
  /** Optional SVG content; a default arrow is rendered when omitted. */
  children?: ReactNode
  className?: string
}

export function Icon({ label, mode = 'preserve', children, className }: IconProps) {
  const classes = ['cu-icon', `cu-icon--${mode}`, className].filter(Boolean).join(' ')

  return (
    <span
      className={classes}
      data-ai-role="icon" data-ai-intent="signal-meaning"
      data-ai-state="default"
      data-mode={mode}
      aria-label={label}
      role="img"
    >
      {children ?? <DefaultIcon />}
    </span>
  )
}

function DefaultIcon() {
  return (
    <svg aria-hidden="true" className="cu-icon__svg" viewBox="0 0 24 24">
      <path
        d="M20 12H4m0 0l6-6m-6 6l6 6"
        fill="none"
        stroke="currentColor"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={2}
      />
    </svg>
  )
}

{
  "icon": {
    "back": "Zurück zur vorherigen Ansicht",
    "menu": "Hauptmenü öffnen",
    "close": "Diesen Dialog schließen"
  }
}

.cu-icon {
  display: inline-flex;
  inline-size: 1em;
  block-size: 1em;
  flex: none;
  color: currentColor;
  vertical-align: middle;
}

.cu-icon--mirror {
  transform: scaleX(-1);
}

.cu-icon__svg {
  inline-size: 100%;
  block-size: 100%;
}
